import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { basename, resolve } from "node:path";

const packageRoot = resolve(import.meta.dirname, "..");
const outputFlag = process.argv.indexOf("--output-root");
const outputRoot = outputFlag >= 0 ? resolve(process.argv[outputFlag + 1] ?? "") : packageRoot;
const definitionPath = resolve(packageRoot, "definition/all-work-v1.contract.json");
const definitionBytes = await readFile(definitionPath);
const definition = JSON.parse(definitionBytes.toString("utf8"));
const definitionDigest = createHash("sha256").update(definitionBytes).digest("hex");

const generatedHeader = (comment) =>
  `${comment} @generated by @openagentsinc/all-work-contract/scripts/generate.mjs\n${comment} Definition: ${definition.contractRef}\n${comment} Definition SHA-256: ${definitionDigest}\n${comment} DO NOT EDIT.\n`;

const sha256 = (value) => createHash("sha256").update(value).digest("hex");
const json = (value) => `${JSON.stringify(value, null, 2)}\n`;
const canonicalize = (value) => {
  if (Array.isArray(value)) return value.map(canonicalize);
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [key, canonicalize(value[key])]),
    );
  }
  return value;
};
const canonicalJson = (value) => JSON.stringify(canonicalize(value));

const writeOutput = async (relativePath, contents) => {
  const path = resolve(outputRoot, relativePath);
  await mkdir(resolve(path, ".."), { recursive: true });
  await writeFile(path, contents);
  return contents;
};

const typeByName = new Map(definition.types.map((type) => [type.name, type]));
const requireType = (name) => {
  const type = typeByName.get(name);
  if (type === undefined) throw new Error(`unknown contract type: ${name}`);
  return type;
};

const unwrapOptional = (expression) =>
  typeof expression === "object" && expression !== null && "optional" in expression
    ? expression.optional
    : expression;
const isOptional = (expression) =>
  typeof expression === "object" && expression !== null && "optional" in expression;
const isNullable = (expression) =>
  typeof expression === "object" && expression !== null && "nullable" in expression;

const validateExpression = (expression) => {
  if (typeof expression === "string") {
    if (expression !== "boolean") requireType(expression);
    return;
  }
  if (expression === null || typeof expression !== "object") {
    throw new Error(`invalid type expression: ${JSON.stringify(expression)}`);
  }
  if ("optional" in expression) return validateExpression(expression.optional);
  if ("nullable" in expression) return validateExpression(expression.nullable);
  if ("array" in expression) {
    validateExpression(expression.array);
    if (expression.minItems !== undefined && expression.minItems < 0) {
      throw new Error("array minItems must be non-negative");
    }
    if (
      expression.minItems !== undefined &&
      expression.maxItems !== undefined &&
      expression.minItems > expression.maxItems
    ) {
      throw new Error("array minItems must not exceed maxItems");
    }
    return;
  }
  throw new Error(`unsupported type expression: ${JSON.stringify(expression)}`);
};

for (const type of definition.types) {
  if (type.kind === "record") {
    for (const field of type.fields) validateExpression(field.type);
  } else if (type.kind === "taggedUnion") {
    for (const variant of type.variants) {
      for (const field of variant.fields) validateExpression(field.type);
    }
  } else if (!["string", "integer", "enum"].includes(type.kind)) {
    throw new Error(`unsupported contract type kind: ${type.kind}`);
  }
}
for (const root of definition.roots) requireType(root);

const quote = (value) => JSON.stringify(value);
const regexLiteral = (value) => `/${value.replaceAll("/", "\\/")}/u`;

const effectExpression = (expression) => {
  if (typeof expression === "string") {
    return expression === "boolean" ? "S.Boolean" : `${expression}Schema`;
  }
  if ("optional" in expression) return `S.optionalKey(${effectExpression(expression.optional)})`;
  if ("nullable" in expression) return `S.NullOr(${effectExpression(expression.nullable)})`;
  if ("array" in expression) {
    const checks = [];
    if (expression.minItems !== undefined) checks.push(`S.isMinLength(${expression.minItems})`);
    if (expression.maxItems !== undefined) checks.push(`S.isMaxLength(${expression.maxItems})`);
    const base = `S.Array(${effectExpression(expression.array)})`;
    return checks.length === 0 ? base : `${base}.check(${checks.join(", ")})`;
  }
  throw new Error(`unsupported Effect expression: ${JSON.stringify(expression)}`);
};

const effectType = (type) => {
  if (type.kind === "string") {
    const checks = [];
    if (type.minLength !== undefined) checks.push(`S.isMinLength(${type.minLength})`);
    if (type.maxLength !== undefined) checks.push(`S.isMaxLength(${type.maxLength})`);
    if (type.pattern !== undefined) checks.push(`S.isPattern(${regexLiteral(type.pattern)})`);
    const checked = checks.length === 0 ? "S.String" : `S.String.check(${checks.join(", ")})`;
    return `export const ${type.name}Schema = ${checked}.pipe(S.brand(${quote(type.name)})).annotate({ identifier: ${quote(type.name)} })\nexport type ${type.name} = typeof ${type.name}Schema.Type\n`;
  }
  if (type.kind === "integer") {
    return `export const ${type.name}Schema = S.Number.check(S.isInt(), S.isGreaterThanOrEqualTo(${type.minimum}), S.isLessThanOrEqualTo(${type.maximum})).pipe(S.brand(${quote(type.name)})).annotate({ identifier: ${quote(type.name)} })\nexport type ${type.name} = typeof ${type.name}Schema.Type\n`;
  }
  if (type.kind === "enum") {
    return `export const ${type.name}Schema = S.Literals([${type.values.map(quote).join(", ")}]).annotate({ identifier: ${quote(type.name)} })\nexport type ${type.name} = typeof ${type.name}Schema.Type\n`;
  }
  if (type.kind === "record") {
    const fields = type.fields
      .map((field) => `  ${quote(field.name)}: ${effectExpression(field.type)},`)
      .join("\n");
    return `export const ${type.name}Schema = S.Struct({\n${fields}\n}).annotate({ identifier: ${quote(type.name)} })\nexport interface ${type.name} extends S.Schema.Type<typeof ${type.name}Schema> {}\n`;
  }
  if (type.kind === "taggedUnion") {
    const variants = type.variants
      .map((variant) => {
        const fields = [
          `    ${quote(type.discriminator)}: S.Literal(${quote(variant.tag)}),`,
          ...variant.fields.map(
            (field) => `    ${quote(field.name)}: ${effectExpression(field.type)},`,
          ),
        ].join("\n");
        return `  S.Struct({\n${fields}\n  }).annotate({ identifier: ${quote(`${type.name}${variant.name}`)} })`;
      })
      .join(",\n");
    return `export const ${type.name}Schema = S.Union([\n${variants},\n], { mode: "oneOf" }).annotate({ identifier: ${quote(type.name)} })\nexport type ${type.name} = typeof ${type.name}Schema.Type\n`;
  }
  throw new Error(`unsupported Effect type: ${type.kind}`);
};

const effectSchemas = definition.types.map(effectType).join("\n");
const effectRootMap = definition.roots.map((name) => `  ${quote(name)}: ${name}Schema,`).join("\n");
const effectDecoders = definition.roots
  .map(
    (name) =>
      `export const decode${name} = (input: unknown): ${name} => S.decodeUnknownSync(${name}Schema)(input, STRICT_DECODE_OPTIONS)`,
  )
  .join("\n");
const effectSource = `${generatedHeader("//")}\nimport { Schema as S } from "effect"\n\nexport const ALL_WORK_CONTRACT_REF = ${quote(definition.contractRef)} as const\nexport const ALL_WORK_CONTRACT_DEFINITION_SHA256 = ${quote(definitionDigest)} as const\nexport const ALL_WORK_MAX_ENCODED_BYTES = ${definition.maximumEncodedBytes} as const\n\n${effectSchemas}\nexport const ALL_WORK_CONTRACT_SCHEMAS = {\n${effectRootMap}\n} as const\n\nexport type AllWorkContractSchemaName = keyof typeof ALL_WORK_CONTRACT_SCHEMAS\n\nconst STRICT_DECODE_OPTIONS = { onExcessProperty: "error" } as const\n\n${effectDecoders}\n`;

const rustName = (value) => {
  const words = value.split(/[^A-Za-z0-9]+/u).filter(Boolean);
  const joined = words.map((word) => `${word[0]?.toUpperCase() ?? ""}${word.slice(1)}`).join("");
  return /^[0-9]/u.test(joined) ? `Value${joined}` : joined;
};
const rustFieldName = (value) =>
  value
    .replace(/([a-z0-9])([A-Z])/gu, "$1_$2")
    .replace(/[^A-Za-z0-9]+/gu, "_")
    .toLowerCase();

const rustExpression = (expression, optionalNullable = false) => {
  if (typeof expression === "string") {
    if (expression === "boolean") return "bool";
    return expression;
  }
  if ("optional" in expression) {
    if (isNullable(expression.optional)) {
      return `Option<Option<${rustExpression(expression.optional.nullable)}>>`;
    }
    return `Option<${rustExpression(expression.optional)}>`;
  }
  if ("nullable" in expression) return `Nullable<${rustExpression(expression.nullable)}>`;
  if ("array" in expression) return `Vec<${rustExpression(expression.array)}>`;
  if (optionalNullable) throw new Error("invalid optional nullable expression");
  throw new Error(`unsupported Rust expression: ${JSON.stringify(expression)}`);
};

const rustFormatCheck = (type) => {
  if (type.formatClass === "reference") return "is_reference(&value)";
  if (type.formatClass === "cursor") return "is_cursor(&value)";
  if (type.formatClass === "sha256") return "is_sha256(&value)";
  if (type.formatClass === "utc_timestamp") return "is_utc_timestamp(&value)";
  return null;
};

const rustType = (type) => {
  if (type.kind === "string") {
    const formatCheck = rustFormatCheck(type);
    const checks = [];
    if (type.minLength === 1) checks.push("value.is_empty()");
    else if (type.minLength !== undefined && type.minLength > 1) {
      checks.push(`value.len() < ${type.minLength}`);
    }
    if (type.maxLength !== undefined) checks.push(`value.len() > ${type.maxLength}`);
    if (formatCheck !== null) checks.push(`!${formatCheck}`);
    return `#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]\n#[serde(try_from = "String", into = "String")]\npub struct ${type.name}(pub String);\n\nimpl TryFrom<String> for ${type.name} {\n    type Error = ContractValidationError;\n\n    fn try_from(value: String) -> Result<Self, Self::Error> {\n        if ${checks.join(" || ") || "false"} {\n            return Err(ContractValidationError::new(${quote(type.name)}, "string constraint failed"));\n        }\n        Ok(Self(value))\n    }\n}\n\nimpl From<${type.name}> for String {\n    fn from(value: ${type.name}) -> Self { value.0 }\n}\n\nimpl ContractValidate for ${type.name} {\n    fn validate(&self) -> Result<(), ContractValidationError> { Ok(()) }\n}\n`;
  }
  if (type.kind === "integer") {
    const minimumCheck = type.minimum > 0 ? `value < ${type.minimum} || ` : "";
    return `#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]\n#[serde(try_from = "u64", into = "u64")]\npub struct ${type.name}(pub u64);\n\nimpl TryFrom<u64> for ${type.name} {\n    type Error = ContractValidationError;\n\n    fn try_from(value: u64) -> Result<Self, Self::Error> {\n        if ${minimumCheck}value > ${type.maximum} {\n            return Err(ContractValidationError::new(${quote(type.name)}, "integer constraint failed"));\n        }\n        Ok(Self(value))\n    }\n}\n\nimpl From<${type.name}> for u64 {\n    fn from(value: ${type.name}) -> Self { value.0 }\n}\n\nimpl ContractValidate for ${type.name} {\n    fn validate(&self) -> Result<(), ContractValidationError> { Ok(()) }\n}\n`;
  }
  if (type.kind === "enum") {
    const variants = type.values
      .map((value) => `    #[serde(rename = ${quote(value)})]\n    ${rustName(value)},`)
      .join("\n");
    return `#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]\npub enum ${type.name} {\n${variants}\n}\n\nimpl ContractValidate for ${type.name} {\n    fn validate(&self) -> Result<(), ContractValidationError> { Ok(()) }\n}\n`;
  }
  if (type.kind === "record") {
    const fields = type.fields
      .map((field) => {
        const expression = field.type;
        const attributes = [];
        if (isOptional(expression) && isNullable(expression.optional)) {
          attributes.push(
            '#[serde(default, with = "double_option", skip_serializing_if = "Option::is_none")]',
          );
        } else if (isNullable(expression)) {
          attributes.push('#[serde(with = "required_nullable")]');
        } else if (isOptional(expression)) {
          attributes.push('#[serde(default, skip_serializing_if = "Option::is_none")]');
        }
        attributes.push(`#[serde(rename = ${quote(field.name)})]`);
        return `${attributes.map((attribute) => `    ${attribute}`).join("\n")}\n    pub ${rustFieldName(field.name)}: ${rustExpression(expression)},`;
      })
      .join("\n");
    const validations = type.fields
      .flatMap((field) => {
        const expression = field.type;
        const actual = unwrapOptional(expression);
        const checks = [];
        if (typeof actual === "object" && actual !== null && "array" in actual) {
          if (actual.minItems !== undefined) {
            const minimumCheck =
              actual.minItems === 1
                ? `self.${rustFieldName(field.name)}.is_empty()`
                : `self.${rustFieldName(field.name)}.len() < ${actual.minItems}`;
            checks.push(
              `        if ${minimumCheck} { return Err(ContractValidationError::new(${quote(`${type.name}.${field.name}`)}, "array is shorter than minItems")); }`,
            );
          }
          if (actual.maxItems !== undefined) {
            checks.push(
              `        if self.${rustFieldName(field.name)}.len() > ${actual.maxItems} { return Err(ContractValidationError::new(${quote(`${type.name}.${field.name}`)}, "array is longer than maxItems")); }`,
            );
          }
        }
        checks.push(`        self.${rustFieldName(field.name)}.validate()?;`);
        return checks;
      })
      .join("\n");
    return `#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]\n#[serde(deny_unknown_fields)]\npub struct ${type.name} {\n${fields}\n}\n\nimpl ContractValidate for ${type.name} {\n    fn validate(&self) -> Result<(), ContractValidationError> {\n${validations}\n        Ok(())\n    }\n}\n`;
  }
  if (type.kind === "taggedUnion") {
    const variants = type.variants
      .map((variant) => {
        const fields = variant.fields
          .map((field) => {
            const attributes = [];
            if (isOptional(field.type) && isNullable(field.type.optional)) {
              attributes.push(
                '#[serde(default, with = "double_option", skip_serializing_if = "Option::is_none")]',
              );
            } else if (isNullable(field.type)) {
              attributes.push('#[serde(with = "required_nullable")]');
            } else if (isOptional(field.type)) {
              attributes.push('#[serde(default, skip_serializing_if = "Option::is_none")]');
            }
            attributes.push(`#[serde(rename = ${quote(field.name)})]`);
            const fieldType = rustExpression(field.type);
            const payloadType = ["params", "result", "error", "item"].includes(field.name)
              ? `Box<${fieldType}>`
              : fieldType;
            return `${attributes.map((attribute) => `        ${attribute}`).join("\n")}\n        ${rustFieldName(field.name)}: ${payloadType},`;
          })
          .join("\n");
        return `    #[serde(rename = ${quote(variant.tag)})]\n    ${variant.name} {\n${fields}\n    },`;
      })
      .join("\n");
    const matches = type.variants
      .map((variant) => {
        const names = variant.fields.map((field) => rustFieldName(field.name));
        const pattern = names.length === 0 ? "" : ` { ${names.join(", ")} }`;
        const checks = names.map((name) => `${name}.validate()?;`).join(" ");
        return `            Self::${variant.name}${pattern} => { ${checks} Ok(()) }`;
      })
      .join("\n");
    return `#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]\n#[serde(tag = ${quote(type.discriminator)}, deny_unknown_fields)]\npub enum ${type.name} {\n${variants}\n}\n\nimpl ContractValidate for ${type.name} {\n    fn validate(&self) -> Result<(), ContractValidationError> {\n        match self {\n${matches}\n        }\n    }\n}\n`;
  }
  throw new Error(`unsupported Rust type: ${type.kind}`);
};

const rustPrelude = `${generatedHeader("//")}\nuse serde::{Deserialize, Deserializer, Serialize, Serializer};\n\npub const ALL_WORK_CONTRACT_REF: &str = ${quote(definition.contractRef)};\npub const ALL_WORK_CONTRACT_DEFINITION_SHA256: &str = ${quote(definitionDigest)};\npub const ALL_WORK_MAX_ENCODED_BYTES: usize = ${definition.maximumEncodedBytes};\n\n#[derive(Clone, Debug, PartialEq, Eq)]\npub struct ContractValidationError {\n    pub path: &'static str,\n    pub message: &'static str,\n}\n\nimpl ContractValidationError {\n    pub const fn new(path: &'static str, message: &'static str) -> Self {\n        Self { path, message }\n    }\n}\n\nimpl std::fmt::Display for ContractValidationError {\n    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {\n        write!(formatter, "{}: {}", self.path, self.message)\n    }\n}\n\nimpl std::error::Error for ContractValidationError {}\n\npub trait ContractValidate {\n    fn validate(&self) -> Result<(), ContractValidationError>;\n}\n\nimpl ContractValidate for bool {\n    fn validate(&self) -> Result<(), ContractValidationError> { Ok(()) }\n}\n\nimpl<T: ContractValidate> ContractValidate for Vec<T> {\n    fn validate(&self) -> Result<(), ContractValidationError> {\n        for value in self { value.validate()?; }\n        Ok(())\n    }\n}\n\nimpl<T: ContractValidate> ContractValidate for Option<T> {\n    fn validate(&self) -> Result<(), ContractValidationError> {\n        if let Some(value) = self { value.validate()?; }\n        Ok(())\n    }\n}\n\n#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]\n#[serde(transparent)]\npub struct Nullable<T>(pub Option<T>);\n\nimpl<T: ContractValidate> ContractValidate for Nullable<T> {\n    fn validate(&self) -> Result<(), ContractValidationError> { self.0.validate() }\n}\n\npub fn canonical_json_bytes<T: Serialize>(value: &T) -> Result<Vec<u8>, serde_json::Error> {\n    fn sort(value: serde_json::Value) -> serde_json::Value {\n        match value {\n            serde_json::Value::Array(values) => serde_json::Value::Array(values.into_iter().map(sort).collect()),\n            serde_json::Value::Object(values) => {\n                let mut entries: Vec<_> = values.into_iter().collect();\n                entries.sort_by(|left, right| left.0.cmp(&right.0));\n                serde_json::Value::Object(entries.into_iter().map(|(key, value)| (key, sort(value))).collect())\n            }\n            other => other,\n        }\n    }\n\n    serde_json::to_vec(&sort(serde_json::to_value(value)?))\n}\n\nmod required_nullable {\n    use super::*;\n\n    pub fn serialize<T: Serialize, S: Serializer>(value: &Nullable<T>, serializer: S) -> Result<S::Ok, S::Error> {\n        value.0.serialize(serializer)\n    }\n\n    pub fn deserialize<'de, T: Deserialize<'de>, D: Deserializer<'de>>(deserializer: D) -> Result<Nullable<T>, D::Error> {\n        Option::<T>::deserialize(deserializer).map(Nullable)\n    }\n}\n\nmod double_option {\n    use super::*;\n\n    pub fn serialize<T: Serialize, S: Serializer>(value: &Option<Option<T>>, serializer: S) -> Result<S::Ok, S::Error> {\n        match value {\n            None | Some(None) => serializer.serialize_none(),\n            Some(Some(inner)) => inner.serialize(serializer),\n        }\n    }\n\n    pub fn deserialize<'de, T: Deserialize<'de>, D: Deserializer<'de>>(deserializer: D) -> Result<Option<Option<T>>, D::Error> {\n        Option::<T>::deserialize(deserializer).map(Some)\n    }\n}\n\nfn is_reference(value: &str) -> bool {\n    let mut chars = value.chars();\n    chars.next().is_some_and(|first| first.is_ascii_alphabetic())\n        && chars.all(|character| character.is_ascii_alphanumeric() || matches!(character, '.' | '_' | ':' | '/' | '-'))\n}\n\nfn is_cursor(value: &str) -> bool {\n    value.chars().next().is_some_and(|first| first.is_ascii_alphanumeric())\n        && value.chars().all(|character| character.is_ascii_alphanumeric() || matches!(character, '.' | '_' | ':' | '/' | '=' | '+' | '-'))\n}\n\nfn is_sha256(value: &str) -> bool {\n    value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))\n}\n\nfn is_utc_timestamp(value: &str) -> bool {\n    value.len() >= 20 && value.len() <= 32 && value.ends_with('Z') && value.as_bytes().get(4) == Some(&b'-') && value.as_bytes().get(7) == Some(&b'-') && value.as_bytes().get(10) == Some(&b'T')\n}\n`;
const rustBoxValidation = `impl<T: ContractValidate> ContractValidate for Box<T> {
    fn validate(&self) -> Result<(), ContractValidationError> {
        self.as_ref().validate()
    }
}`;
const rustSource = `${rustPrelude}\n${rustBoxValidation}\n\n${definition.types.map(rustType).join("\n")}`;

const jsonSchemaExpression = (expression) => {
  if (typeof expression === "string") {
    return expression === "boolean" ? { type: "boolean" } : { $ref: `#/$defs/${expression}` };
  }
  if ("optional" in expression) return jsonSchemaExpression(expression.optional);
  if ("nullable" in expression) {
    return { anyOf: [jsonSchemaExpression(expression.nullable), { type: "null" }] };
  }
  if ("array" in expression) {
    const schema = { type: "array", items: jsonSchemaExpression(expression.array) };
    if (expression.minItems !== undefined) schema.minItems = expression.minItems;
    if (expression.maxItems !== undefined) schema.maxItems = expression.maxItems;
    return schema;
  }
  throw new Error(`unsupported JSON Schema expression: ${JSON.stringify(expression)}`);
};

const jsonSchemaType = (type) => {
  if (type.kind === "string") {
    const schema = { type: "string", title: type.name, "x-openagents-brand": type.name };
    if (type.minLength !== undefined) schema.minLength = type.minLength;
    if (type.maxLength !== undefined) schema.maxLength = type.maxLength;
    if (type.pattern !== undefined) schema.pattern = type.pattern;
    return schema;
  }
  if (type.kind === "integer") {
    return {
      type: "integer",
      title: type.name,
      minimum: type.minimum,
      maximum: type.maximum,
      "x-openagents-integer-representation": "json-safe-integer",
    };
  }
  if (type.kind === "enum") return { type: "string", title: type.name, enum: type.values };
  if (type.kind === "record") {
    return {
      type: "object",
      title: type.name,
      properties: Object.fromEntries(
        type.fields.map((field) => [field.name, jsonSchemaExpression(unwrapOptional(field.type))]),
      ),
      required: type.fields.filter((field) => !isOptional(field.type)).map((field) => field.name),
      additionalProperties: false,
    };
  }
  if (type.kind === "taggedUnion") {
    return {
      title: type.name,
      oneOf: type.variants.map((variant) => ({
        type: "object",
        properties: {
          [type.discriminator]: { const: variant.tag },
          ...Object.fromEntries(
            variant.fields.map((field) => [
              field.name,
              jsonSchemaExpression(unwrapOptional(field.type)),
            ]),
          ),
        },
        required: [
          type.discriminator,
          ...variant.fields.filter((field) => !isOptional(field.type)).map((field) => field.name),
        ],
        additionalProperties: false,
      })),
    };
  }
  throw new Error(`unsupported JSON Schema type: ${type.kind}`);
};

const jsonSchema = {
  $schema: "https://json-schema.org/draft/2020-12/schema",
  $id: `https://openagents.com/schemas/${definition.contractRef}.schema.json`,
  title: definition.title,
  oneOf: definition.roots.map((root) => ({ $ref: `#/$defs/${root}` })),
  $defs: Object.fromEntries(definition.types.map((type) => [type.name, jsonSchemaType(type)])),
  "x-openagents": {
    profileVersion: definition.profileVersion,
    contractRef: definition.contractRef,
    contractVersion: definition.contractVersion,
    definitionSha256: definitionDigest,
    owningDomain: definition.owningDomain,
    authoritativeRuntime: definition.authoritativeRuntime,
    relationship: definition.relationship,
    canonicalEncoding: definition.canonicalEncoding,
    canonicalEncodingRules: definition.canonicalEncodingRules,
    maximumEncodedBytes: definition.maximumEncodedBytes,
    unknownFieldPolicy: definition.unknownFieldPolicy,
    unknownVariantPolicy: definition.unknownVariantPolicy,
    compatibilityPolicy: definition.compatibilityPolicy,
    capability: definition.capability,
    minimumProtocolVersion: definition.minimumProtocolVersion,
    semanticChecks: definition.semanticChecks,
  },
};

const fixtureIndex = {
  contractRef: definition.contractRef,
  definitionSha256: definitionDigest,
  fixtures: definition.fixtures.map((fixture) => ({
    file: fixture.file,
    schema: fixture.schema,
    valid: fixture.valid,
    canonical: fixture.canonical === true,
  })),
};

for (const fixture of definition.fixtures) {
  if (!definition.roots.includes(fixture.schema)) {
    throw new Error(`fixture ${fixture.file} uses non-root schema ${fixture.schema}`);
  }
  await writeOutput(`fixtures/${fixture.file}`, json(fixture.value));
  if (fixture.canonical === true) {
    await writeOutput(
      `generated/canonical/${basename(fixture.file, ".json")}.canonical.json`,
      canonicalJson(fixture.value),
    );
  }
}

await writeOutput("src/generated.ts", effectSource);
await writeOutput("generated/rust/all_work_v1.rs", rustSource);
const effectPath = resolve(outputRoot, "src/generated.ts");
const rustPath = resolve(outputRoot, "generated/rust/all_work_v1.rs");
execFileSync(resolve(packageRoot, "node_modules/.bin/vp"), ["fmt", effectPath], {
  cwd: packageRoot,
  stdio: "pipe",
});
execFileSync("rustfmt", ["--edition", "2021", rustPath], { stdio: "pipe" });
const [effectContents, rustContents] = await Promise.all([
  readFile(effectPath, "utf8"),
  readFile(rustPath, "utf8"),
]);
const schemaContents = await writeOutput(
  "generated/json-schema/all-work-v1.schema.json",
  json(jsonSchema),
);
const fixtureIndexContents = await writeOutput("generated/fixture-index.json", json(fixtureIndex));

const compatibilityManifest = {
  contractRef: definition.contractRef,
  contractVersion: definition.contractVersion,
  profileVersion: definition.profileVersion,
  definitionSha256: definitionDigest,
  artifacts: {
    effectSha256: sha256(effectContents),
    rustSha256: sha256(rustContents),
    jsonSchemaSha256: sha256(schemaContents),
    fixtureIndexSha256: sha256(fixtureIndexContents),
  },
  protocol: {
    supportedVersions: ["omega-effectd.v1", "omega-effectd.v2"],
    v1Posture: "explicit-negotiation-rollback-only",
    methods: definition.methods,
  },
  compatibilityPolicy: definition.compatibilityPolicy,
  canonicalEncoding: definition.canonicalEncoding,
  canonicalEncodingRules: definition.canonicalEncodingRules,
  unknownFieldPolicy: definition.unknownFieldPolicy,
  unknownVariantPolicy: definition.unknownVariantPolicy,
  semanticChecks: definition.semanticChecks,
};
await writeOutput("generated/compatibility.json", json(compatibilityManifest));
